import { useCallback } from 'react'

import { useQuery } from '@tanstack/react-query'

import { Box, CircularProgress, Typography } from '@mui/material'

import { useOctokit } from '../hooks'
import { getImageDataUrl, getTextFileContent } from '../lib/github'

import { MarkdownView } from './MarkdownView'

export type MarkdownFileViewProps = {
  owner: string
  repo: string
  path: string
}

/** `path`가 속한 디렉토리(repo 루트 기준). 최상위 파일이면 빈 문자열. */
function dirOf(path: string): string {
  const index = path.lastIndexOf('/')
  return index < 0 ? '' : path.slice(0, index)
}

function joinPath(...segments: string[]): string {
  return segments.filter(Boolean).join('/')
}

/**
 * 플래시카드가 아닌 일반 마크다운 파일 본문.
 * 힌트 산출물(README/hi)과 동일한 방식으로 렌더링한다:
 * markdown-it + KaTeX + highlight.js, 상대 경로 이미지는 파일이 있는 디렉토리 기준으로
 * data URL로 치환한다(텍스트 먼저 표시하고 이미지는 각자 Suspense로 도착하는 대로 표시).
 */
export function MarkdownFileView({ owner, repo, path }: MarkdownFileViewProps) {
  const octokit = useOctokit()
  const baseDir = dirOf(path)

  const { data: text, isLoading } = useQuery({
    queryKey: ['flashManMarkdownFile', owner, repo, path],
    queryFn: () => getTextFileContent(octokit, { owner, repo }, path),
    staleTime: 1000 * 60 * 5,
    retry: false,
  })

  const resolveImage = useCallback(
    async (imageUrl: string) => {
      const dataUrl = await getImageDataUrl(octokit, { owner, repo }, joinPath(baseDir, imageUrl))
      return dataUrl ?? imageUrl
    },
    [octokit, owner, repo, baseDir]
  )

  if (isLoading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress size={28} />
      </Box>
    )
  }

  if (text == null) {
    return (
      <Typography variant="body2" color="text.secondary" sx={{ py: 2 }}>
        파일을 불러오지 못했습니다: {path}
      </Typography>
    )
  }

  return (
    <MarkdownView
      variant="doc"
      markdown={text}
      resolveImage={resolveImage}
      imageScope={`${owner}/${repo}/${baseDir}`}
    />
  )
}

export default MarkdownFileView
